#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int r, c;
    if (scanf("%d %d", &r, &c) != 2) return 0;
    int **mat = malloc((size_t)r * sizeof(int *));
    if (mat == NULL) return 1;
    for (int i = 0; i < r; i++) {
        mat[i] = malloc((size_t)c * sizeof(int));
        if (mat[i] == NULL) {
            for (int k = 0; k < i; k++) free(mat[k]);
            free(mat);
            return 1;
        }
        for (int j = 0; j < c; j++) {
            if (scanf("%d", &mat[i][j]) != 1) {
                for (int k = 0; k <= i; k++) free(mat[k]);
                free(mat);
                return 0;
            }
        }
    }
    int **t = malloc((size_t)c * sizeof(int *));
    if (t == NULL) {
        for (int i = 0; i < r; i++) free(mat[i]);
        free(mat);
        return 1;
    }
    for (int i = 0; i < c; i++) {
        t[i] = malloc((size_t)r * sizeof(int));
        if (t[i] == NULL) {
            for (int k = 0; k < i; k++) free(t[k]);
            free(t);
            for (int j = 0; j < r; j++) free(mat[j]);
            free(mat);
            return 1;
        }
        for (int j = 0; j < r; j++) {
            t[i][j] = mat[j][i];
        }
    }
    for (int i = 0; i < c; i++) {
        for (int j = 0; j < r; j++) {
            if (j) putchar(' ');
            printf("%d", t[i][j]);
        }
        putchar('\n');
    }
    for (int i = 0; i < c; i++) free(t[i]);
    free(t);
    for (int i = 0; i < r; i++) free(mat[i]);
    free(mat);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int cap = 1;
    int size = 0;
    int *stack = malloc((size_t)cap * sizeof(int));
    if (stack == NULL) return 1;
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) { free(stack); return 0; }
        if (size == cap) {
            int newcap = cap * 2;
            int *tmp = realloc(stack, (size_t)newcap * sizeof(int));
            if (tmp == NULL) { free(stack); return 1; }
            stack = tmp;
            cap = newcap;
        }
        stack[size++] = v;
    }
    for (int i = 0; i < size; i++) {
        if (i) putchar(' ');
        printf("%d", stack[i]);
    }
    putchar('\n');
    free(stack);
    return 0;
}

