#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int *freq = calloc(101, sizeof(int));
    if (freq == NULL) return 1;
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) { free(freq); return 0; }
        if (v >= 0 && v <= 100) freq[v]++;
    }
    int best_val = 0;
    int best_count = freq[0];
    for (int v = 1; v <= 100; v++) {
        if (freq[v] > best_count) {
            best_count = freq[v];
            best_val = v;
        }
    }
    printf("%d\n", best_val);
    free(freq);
    return 0;
}
